import { useState, useEffect, useRef } from 'react';
import * as THREE from 'three';
import useUsers from './hooks/useUsers';
import UserTable from './components/UserTable';
import UserForm from './components/UserForm';
import Notification from './components/Notification';
import Chat from './components/Chat';
import LoginModal from './components/LoginModal';

const styles = `
  @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;700;900&family=Exo+2:wght@300;400;600&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: #000;
    font-family: 'Exo 2', sans-serif;
    color: #e0f0ff;
    min-height: 100vh;
    overflow-x: hidden;
    cursor: none;
  }

  /* ============================================
     WATER RIPPLE CURSOR STYLES
     ============================================ */
  #ripple-container {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 9999;
    overflow: hidden;
  }

  .ripple {
    position: absolute;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(0,170,255,0.8) 0%, rgba(0,255,238,0.4) 30%, rgba(0,170,255,0) 70%);
    transform: translate(-50%, -50%) scale(0);
    animation: rippleExpand 0.8s cubic-bezier(0.2, 0.9, 0.4, 1.1) forwards;
    pointer-events: none;
    filter: blur(2px);
    box-shadow: 0 0 20px rgba(0,170,255,0.8), 0 0 40px rgba(0,255,238,0.4);
  }

  @keyframes rippleExpand {
    0% {
      transform: translate(-50%, -50%) scale(0);
      opacity: 0.9;
    }
    50% {
      opacity: 0.6;
    }
    100% {
      transform: translate(-50%, -50%) scale(1);
      opacity: 0;
    }
  }

  .fast-ripple {
    background: radial-gradient(circle, rgba(255,51,102,0.9) 0%, rgba(0,255,238,0.5) 40%, rgba(0,170,255,0) 70%);
    box-shadow: 0 0 40px rgba(255,51,102,0.8), 0 0 60px rgba(0,255,238,0.5);
  }

  #cursor-glow {
    position: fixed;
    width: 12px;
    height: 12px;
    background: radial-gradient(circle, #00ffee, #00aaff);
    border-radius: 50%;
    pointer-events: none;
    z-index: 10000;
    box-shadow: 0 0 30px #00ffee, 0 0 60px #00aaff, 0 0 90px rgba(0,170,255,0.5);
    transition: transform 0.05s linear;
    filter: blur(1px);
    animation: glowPulse 1.5s ease-in-out infinite;
  }

  @keyframes glowPulse {
    0%, 100% {
