  .plus-icon { width: 30px; height: 30px; border-radius: 8px; background: rgba(0, 100, 255, 0.15); border: 1px solid rgba(0, 100, 255, 0.3); display: flex; align-items: center; justify-content: center; font-size: 20px; color: #00ccff; }
